Shader "Custom/ScannerPostProcess"
{
    Properties
    {
        _MainTex ("Source", 2D) = "white" {}
        _ScanSpeed ("Scan Speed", Float) = 2.0
        _LineThickness ("Line Thickness", Float) = 200.0
        _ScanColor ("Scan Color", Color) = (0, 1, 1, 0.3)
    }

    // URP / legacy OnRenderImage blit
    SubShader
    {
        Tags { "RenderType"="Opaque" "RenderPipeline"="UniversalPipeline" }
        Pass
        {
            ZTest Always
            ZWrite Off
            Cull Off

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);

            float _ScanSpeed;
            float _LineThickness;
            float4 _ScanColor;

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            Varyings vert(Attributes input)
            {
                Varyings output;
                output.positionCS = TransformObjectToHClip(input.positionOS.xyz);
                output.uv = input.uv;
                return output;
            }

            float4 frag(Varyings input) : SV_Target
            {
                float4 screenColor = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);
                float scan = frac(input.uv.y * _LineThickness + _Time.y * _ScanSpeed);
                scan = step(0.95, scan);
                return lerp(screenColor, _ScanColor, scan * _ScanColor.a);
            }
            ENDHLSL
        }
    }

    // HDRP Custom Pass / fullscreen blit (same property names)
    SubShader
    {
        Tags { "RenderType"="Opaque" "RenderPipeline"="HDRenderPipeline" }
        Pass
        {
            Name "ScannerFullscreen"
            ZTest Always
            ZWrite Off
            Cull Off

            HLSLPROGRAM
            #pragma target 4.5
            #pragma vertex Vert
            #pragma fragment Frag

            #include "Packages/com.unity.render-pipelines.core/ShaderLibrary/Common.hlsl"
            #include "Packages/com.unity.render-pipelines.high-definition/Runtime/RenderPipeline/RenderPass/CustomPass/CustomPassCommon.hlsl"

            float _ScanSpeed;
            float _LineThickness;
            float4 _ScanColor;

            float4 Frag(Varyings input) : SV_Target
            {
                float2 uv = input.uv;
                float4 screenColor = float4(CustomPassLoadCameraColor(uv, 0), 1);
                float scan = frac(uv.y * _LineThickness + _Time.y * _ScanSpeed);
                scan = step(0.95, scan);
                return lerp(screenColor, _ScanColor, scan * _ScanColor.a);
            }
            ENDHLSL
        }

        // Fallback fullscreen using _MainTex when used as a simple blit material
        Pass
        {
            Name "ScannerBlit"
            ZTest Always
            ZWrite Off
            Cull Off

            HLSLPROGRAM
            #pragma target 4.5
            #pragma vertex vert
            #pragma fragment frag

            #include "Packages/com.unity.render-pipelines.core/ShaderLibrary/Common.hlsl"
            #include "Packages/com.unity.render-pipelines.core/ShaderLibrary/SpaceTransforms.hlsl"

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);

            float _ScanSpeed;
            float _LineThickness;
            float4 _ScanColor;

            struct Attributes
            {
                uint vertexID : SV_VertexID;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            Varyings vert(Attributes input)
            {
                Varyings output;
                output.positionCS = GetFullScreenTriangleVertexPosition(input.vertexID);
                output.uv = GetFullScreenTriangleTexCoord(input.vertexID);
                return output;
            }

            float4 frag(Varyings input) : SV_Target
            {
                float4 screenColor = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);
                float scan = frac(input.uv.y * _LineThickness + _Time.y * _ScanSpeed);
                scan = step(0.95, scan);
                return lerp(screenColor, _ScanColor, scan * _ScanColor.a);
            }
            ENDHLSL
        }
    }
}

Shader "Custom/ScannerPostProcessPBR"
{
    Properties
    {
        _MainTex ("Color Map", 2D) = "white" {}
        _NormalMap ("Normal Map", 2D) = "bump" {}
        _OcclusionMap ("Occlusion Map", 2D) = "white" {}
        _Metallic ("Metallic", Range(0,1)) = 0.0
        _Smoothness ("Smoothness", Range(0,1)) = 0.5
        _Occlusion ("Ambient Occlusion", Range(0,1)) = 1.0
        _ScanSpeed ("Scan Speed", Float) = 2.0
        _LineThickness ("Line Thickness", Float) = 200.0
        _ScanColor ("Scan Color", Color) = (0,1,1,0.3)
    }

    // URP — surface overlay with scanlines (legacy naming; not full PBR lighting)
    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" "RenderPipeline"="UniversalPipeline" }

        Pass
        {
            Blend SrcAlpha OneMinusSrcAlpha
            ZWrite Off

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);
            TEXTURE2D(_OcclusionMap);
            SAMPLER(sampler_OcclusionMap);

            float _Occlusion;
            float _ScanSpeed;
            float _LineThickness;
            float4 _ScanColor;

            Varyings vert(Attributes input)
            {
                Varyings output;
                output.positionCS = TransformObjectToHClip(input.positionOS.xyz);
                output.uv = input.uv;
                return output;
            }

            float4 frag(Varyings input) : SV_Target
            {
                float scan = frac(input.uv.y * _LineThickness + _Time.y * _ScanSpeed);
                scan = step(0.95, scan);

                float4 color = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);
                float ao = SAMPLE_TEXTURE2D(_OcclusionMap, sampler_OcclusionMap, input.uv).r * _Occlusion;

                return lerp(color, _ScanColor, scan * _ScanColor.a * ao);
            }
            ENDHLSL
        }
    }

    // HDRP
    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" "RenderPipeline"="HDRenderPipeline" }

        Pass
        {
            Name "ForwardUnlit"
            Tags { "LightMode" = "ForwardOnly" }

            Blend SrcAlpha OneMinusSrcAlpha
            ZWrite Off
            Cull Off

            HLSLPROGRAM
            #pragma target 4.5
            #pragma vertex vert
            #pragma fragment frag

            #include "Packages/com.unity.render-pipelines.core/ShaderLibrary/Common.hlsl"
            #include "Packages/com.unity.render-pipelines.core/ShaderLibrary/SpaceTransforms.hlsl"
            #include "Packages/com.unity.render-pipelines.high-definition/Runtime/ShaderLibrary/ShaderVariables.hlsl"

            struct Attributes
            {
                float4 positionOS : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            TEXTURE2D(_MainTex);
            SAMPLER(sampler_MainTex);
            TEXTURE2D(_OcclusionMap);
            SAMPLER(sampler_OcclusionMap);

            float _Occlusion;
            float _ScanSpeed;
            float _LineThickness;
            float4 _ScanColor;

            Varyings vert(Attributes input)
            {
                Varyings output;
                float3 positionWS = TransformObjectToWorld(input.positionOS.xyz);
                output.positionCS = TransformWorldToHClip(positionWS);
                output.uv = input.uv;
                return output;
            }

            float4 frag(Varyings input) : SV_Target
            {
                float scan = frac(input.uv.y * _LineThickness + _Time.y * _ScanSpeed);
                scan = step(0.95, scan);

                float4 color = SAMPLE_TEXTURE2D(_MainTex, sampler_MainTex, input.uv);
                float ao = SAMPLE_TEXTURE2D(_OcclusionMap, sampler_OcclusionMap, input.uv).r * _Occlusion;

                return lerp(color, _ScanColor, scan * _ScanColor.a * ao);
            }
            ENDHLSL
        }
    }
}

using UnityEngine;
using UnityEngine.Rendering.HighDefinition;

namespace Project.Rendering
{
    /// <summary>
    /// HDRP Custom Pass that applies <c>Custom/ScannerPostProcess</c> as a fullscreen scanline overlay.
    /// URP continues to use <see cref="ScannerPostProcess"/> (OnRenderImage) when available.
    /// Dual-pipeline choice: keep URP component + HDRP Custom Pass; do not force Phase 6.
    /// </summary>
    public sealed class ScannerHdrpCustomPass : CustomPass
    {
        [SerializeField] private Material scanlinesMaterial;
        [SerializeField] private float scanSpeed = 2f;
        [SerializeField] private float lineThickness = 200f;
        [SerializeField] private Color scanColor = new Color(0f, 1f, 1f, 0.3f);

        protected override void Setup(ScriptableRenderContext renderContext, CommandBuffer cmd)
        {
            if (scanlinesMaterial == null)
            {
                Shader shader = Shader.Find("Custom/ScannerPostProcess");
                if (shader != null)
                    scanlinesMaterial = CoreUtils.CreateEngineMaterial(shader);
            }
        }

        protected override void Execute(CustomPassContext ctx)
        {
            if (scanlinesMaterial == null)
                return;

            scanlinesMaterial.SetFloat("_ScanSpeed", scanSpeed);
            scanlinesMaterial.SetFloat("_LineThickness", lineThickness);
            scanlinesMaterial.SetColor("_ScanColor", scanColor);

            // Pass 0 = CustomPassLoadCameraColor path when CustomPassCommon is included.
            CoreUtils.SetRenderTarget(ctx.cmd, ctx.cameraColorBuffer, ClearFlag.None);
            CoreUtils.DrawFullScreen(ctx.cmd, scanlinesMaterial, shaderPassId: 0);
        }

        protected override void Cleanup()
        {
            // Engine materials created in Setup are destroyed with the pass volume.
        }
    }
}

